// Simulates the generic event-to-DOM plumbing which is a false positive when
// the file is analyzed as extension logic.  The entire vendor file must be a
// boundary, not just this particular helper.
window.addEventListener("jquery-internal", function (event) {
  document.getElementById("library-output").innerHTML = event.detail;
});
